import numpy as np
import matplotlib.pyplot as plt

# GNU Radio parameters
samp_rate = 32000.0

# Input/output files
input_file = "ch21_exp4_pll_phase_error.dat"
output_file = "ch21-exp4-pll-acquisition-phase-error.png"

# Read float32 phase-error samples generated by GNU Radio
phase_error_rad = np.fromfile(input_file, dtype=np.float32)

# Convert sample index to time in milliseconds
time_ms = np.arange(len(phase_error_rad)) / samp_rate * 1000.0

# Convert phase error from radians to degrees
phase_error_deg = np.degrees(phase_error_rad)

# Plot the measured PLL acquisition transient
plt.figure(figsize=(8, 4.8))
plt.plot(time_ms, phase_error_deg)
plt.xlabel("Time (ms)")
plt.ylabel("Phase Error (degrees)")
plt.title("PLL Acquisition: Phase Error Converging Toward Lock")
plt.grid(True, alpha=0.3)
plt.tight_layout()

plt.savefig(output_file, dpi=200)
plt.show()
